import os

import yaml


class ConfigLoader(object):
    """Module reading configuration from yaml file"""
    REQUIRED_SECTIONS = ["USSD_CODES"]

    def __init__(self, config_path):
        """INIT"""
        self.config_path = config_path

    def load_config(self):
        """
        Load and return configuration from yaml
        :return:
        """
        try:
            with open(self.config_path, 'r') as config_file:
                config = yaml.load(stream=config_file, Loader=yaml.FullLoader)
                self._check_syntax(config)
            return config
        except IOError:
            raise ConfigurationFileNotFound('File does not exist: {}, current folder:{}'.format(self.config_path, os.path.abspath(__file__)))

    def _check_syntax(self, config):
        found_sections = []
        for section in config:
            for allowed_section in self.REQUIRED_SECTIONS:
                if section == allowed_section:
                    found_sections.append(section)
        if found_sections != self.REQUIRED_SECTIONS:
            raise WrongSyntaxInConfigurationFile("Required sections: {}. Check syntax in your config file.".format(self.REQUIRED_SECTIONS))


class ConfigurationFileNotFound(Exception):
    """Thrown when config file is not found"""
    pass


class WrongSyntaxInConfigurationFile(Exception):
    """Thrown when config file has invalid syntax"""
    pass
